var nodes = java.getElements("class.listmain@tag.dl@children");
var inFullToc = false;
nodes.filter(function (node) {
    var html = String(node);
    if (/^<dt\b/i.test(html)) {
        inFullToc = html.indexOf("最新章节") === -1;
    }
    return inFullToc && /^<dd\b/i.test(html);
});

